NACSXNE2.ol:
VAR_x := 1.0 - 2.0 * (NCAD4NE2.raw * NCAD4NE2.raw + NCAD4NE3.raw * NCAD4NE3.raw);
VAR_y := 2.0 * (NCAD6VL2.raw * NCAD4NE2.raw + NCAD4NE3.raw * NCAD6VL1.raw);

if VAR_x > 0 then
return(arctan(VAR_y/VAR_x)*180/3.1415926);
else
		if VAR_x < 0 and VAR_y < 0 then
		return((arctan(VAR_y/VAR_x)-3.1415926)*180/3.1415926);
		else 
		return((arctan(VAR_y/VAR_x)+3.1415926)*180/3.1415926);
		endif;
endif;

NIASX001.ol:
# Determine applicability for PAS OOL
#
VAR_PAS_SciReady := NIAD0763.raw;
VAR_PAS_Mode     := NIAD4423.raw;
#
# OK if SciReady = 3 or Mode = 1, 2 or 3
#
if (VAR_PAS_SciReady == 3) lor ((VAR_PAS_Mode > 0) land (VAR_PAS_Mode < 4)) then
  return (1);
else
#
return (0);
endif;
